use std::io::Write;
use std::process::exit;

const SHADER: &str = r#"
struct Params { width: u32, height: u32 }
@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= params.width || id.y >= params.height) { return; }
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy++) {
        for (var dx: i32 = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) { continue; }
            let x = i32(id.x) + dx;
            let y = i32(id.y) + dy;
            if (x < 0 || y < 0 || x >= i32(params.width) || y >= i32(params.height)) { continue; }
            n += src[u32(y) * params.width + u32(x)];
        }
    }
    let i = id.y * params.width + id.x;
    let alive = src[i] == 1u;
    dst[i] = select(u32(n == 3u), u32(n == 2u || n == 3u), alive);
}
"#;

fn fail(msg: &str) -> ! {
    eprintln!("error: {msg}");
    exit(1);
}

fn parse(text: &str) -> (usize, usize, u32, Vec<u32>) {
    let mut it = text.split_whitespace();
    let mut num = |what: &str| -> usize {
        it.next()
            .and_then(|t| t.parse::<usize>().ok())
            .unwrap_or_else(|| fail(&format!("bad {what}")))
    };
    let w = num("width");
    let h = num("height");
    let g = num("generations");
    if w == 0 || h == 0 {
        fail("empty grid");
    }
    let mut cells = Vec::with_capacity(w * h);
    for t in it.by_ref() {
        // Tolerate rows given without separating spaces.
        for c in t.chars() {
            match c {
                '0' => cells.push(0),
                '1' => cells.push(1),
                _ => fail("bad cell"),
            }
        }
    }
    if cells.len() != w * h {
        fail("wrong number of cells");
    }
    (w, h, g as u32, cells)
}

fn main() {
    let path = std::env::args().nth(1).unwrap_or_else(|| fail("missing input path"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| fail(&e.to_string()));
    let (w, h, gens, cells) = parse(&text);
    let result = pollster::block_on(run(w, h, gens, &cells));

    let mut out = String::with_capacity(w * h * 2 + 32);
    for row in result.chunks(w) {
        let line: Vec<&str> = row.iter().map(|&c| if c == 1 { "1" } else { "0" }).collect();
        out.push_str(&line.join(" "));
        out.push('\n');
    }
    let alive = result.iter().filter(|&&c| c == 1).count();
    out.push_str(&format!("ALIVE {alive}\n"));
    std::io::stdout().write_all(out.as_bytes()).unwrap();
}

async fn run(w: usize, h: usize, gens: u32, cells: &[u32]) -> Vec<u32> {
    use wgpu::util::DeviceExt;
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions::default())
        .await
        .unwrap_or_else(|e| fail(&format!("no GPU adapter: {e}")));
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .unwrap_or_else(|e| fail(&format!("no device: {e}")));

    let size = (w * h * 4) as u64;
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(cells),
        usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage,
        mapped_at_creation: false,
    });
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: None,
        contents: bytemuck::cast_slice(&[w as u32, h as u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: None,
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: None,
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: None,
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: params.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
            ],
        })
    };
    let groups = [make_group(&buf_a, &buf_b), make_group(&buf_b, &buf_a)];

    let mut encoder = device.create_command_encoder(&Default::default());
    for g in 0..gens as usize {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[g % 2], &[]);
        pass.dispatch_workgroups(w.div_ceil(16) as u32, h.div_ceil(16) as u32, 1);
    }
    let final_buf = if gens % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(final_buf, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    slice.map_async(wgpu::MapMode::Read, |r| r.unwrap());
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .unwrap_or_else(|e| fail(&format!("poll failed: {e}")));
    let data = slice.get_mapped_range();
    bytemuck::cast_slice::<u8, u32>(&data).to_vec()
}
